body.script:
const START =
  "https://raw.githack.com/Bubba7004/minty-proxy-assets/HEAD/games/index-261014.html";

function patch() {
  const HTML_HOSTS = new Set([
    "raw.githack.com",
    "rawcdn.githack.com"
  ]);

  function cdnHtml(value) {
    try {
      const url = new URL(value, document.baseURI);

      if (url.protocol !== "https:") return null;
      if (!/\.html?$/i.test(url.pathname)) return null;

      if (HTML_HOSTS.has(url.hostname)) {
        return url.href;
      }

      // Convert jsDelivr GitHub HTML links to raw.githack.
      if (url.hostname === "cdn.jsdelivr.net") {
        const match = url.pathname.match(
          /^\/gh\/([^/]+)\/([^/@]+)(?:@([^/]+))?\/(.+)$/
        );

        if (!match) return null;

        const [, owner, repo, version, path] = match;
        const ref =
          !version || version === "latest" ? "HEAD" : version;

        return (
          "https://raw.githack.com/" +
          owner + "/" +
          repo + "/" +
          ref + "/" +
          path +
          url.search +
          url.hash
        );
      }

      return null;
    } catch {
      return null;
    }
  }

  function rewrite(source) {
    const L = String.raw`(?<![\w$.])(?:(?:window|self|top|parent|document)\.)?location`;

    return source
      .replace(
        new RegExp(
          L + String.raw`\.(?:assign|replace)\s*\(`,
          "g"
        ),
        "__go("
      )
      .replace(
        new RegExp(
          L + String.raw`(?:\.href)?\s*=(?!=)\s*([^;\n}]+)`,
          "g"
        ),
        "__go($1)"
      );
  }

  async function build(value) {
    const target = cdnHtml(value) ||
      new URL(value, document.baseURI).href;

    const response = await fetch(target);
    const text = await response.text();

    if (!response.ok) {
      throw new Error(
        "Failed to load " + target +
        "\nHTTP " + response.status +
        "\n" + text.slice(0, 500)
      );
    }

    if (/^\s*Package size exceeded the configured limit/i.test(text)) {
      throw new Error(text.trim());
    }

    const html = rewrite(text);

    const base = document.createElement("base");
    base.href = (response.url || target).split("#")[0];

    const inject =
      base.outerHTML +
      "<scr" + "ipt>(" +
      patch.toString() +
      ")()</scr" + "ipt>";

    return /<head[^>]*>/i.test(html)
      ? html.replace(/<head[^>]*>/i, (m) => m + inject)
      : inject + html;
  }

  window.__build = build;

  function showError(frame, error) {
    console.error(error);

    const message = String(
      error && error.message ? error.message : error
    );

    const escaped = message.replace(/[&<>"]/g, (character) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;"
    }[character]));

    frame.srcdoc =
      '<!doctype html><html><head>' +
      '<meta name="viewport" content="width=device-width,initial-scale=1">' +
      '</head><body style="margin:0;padding:24px;' +
      'background:#111;color:#eee;font-family:system-ui,sans-serif;">' +
      '<h2>Unable to load the page</h2>' +
      '<pre style="white-space:pre-wrap;overflow-wrap:anywhere;">' +
      escaped +
      '</pre></body></html>';
  }

  function fill(frame, value) {
    const url = cdnHtml(value);
    if (!url || frame.__cdnUrl === url) return;

    frame.__cdnUrl = url;

    build(url)
      .then((html) => {
        // Ignore a response if a newer navigation has started.
        if (frame.__cdnUrl !== url) return;
        frame.srcdoc = html;
      })
      .catch((error) => {
        if (frame.__cdnUrl !== url) return;
        frame.__cdnUrl = null;
        showError(frame, error);
      });
  }

  window.__fill = fill;

  window.__go = function(value) {
    const url = cdnHtml(value);

    if (url && window.parent !== window) {
      window.parent.postMessage(
        { __nav: true, url: url },
        "*"
      );
    } else {
      location.href = new URL(value, document.baseURI).href;
    }
  };

  window.addEventListener("message", (event) => {
    const data = event.data;

    if (
      !data ||
      data.__nav !== true ||
      typeof data.url !== "string"
    ) {
      return;
    }

    const url = cdnHtml(data.url);
    if (!url) return;

    for (const frame of document.querySelectorAll("iframe")) {
      if (frame.contentWindow === event.source) {
        fill(frame, url);
        return;
      }
    }
  });

  const descriptor = Object.getOwnPropertyDescriptor(
    HTMLIFrameElement.prototype,
    "src"
  );

  Object.defineProperty(HTMLIFrameElement.prototype, "src", {
    configurable: descriptor.configurable,
    enumerable: descriptor.enumerable,

    get() {
      return descriptor.get.call(this);
    },

    set(value) {
      const url = cdnHtml(value);

      if (url) {
        fill(this, url);
      } else {
        this.__cdnUrl = null;
        this.removeAttribute("srcdoc");
        descriptor.set.call(this, value);
      }
    }
  });

  const originalSetAttribute = Element.prototype.setAttribute;

  Element.prototype.setAttribute = function(name, value) {
    if (
      this instanceof HTMLIFrameElement &&
      String(name).toLowerCase() === "src"
    ) {
      const url = cdnHtml(value);

      if (url) {
        fill(this, url);
        return;
      }

      this.__cdnUrl = null;
      this.removeAttribute("srcdoc");
    }

    return originalSetAttribute.call(this, name, value);
  };

  function check(frame) {
    const raw = frame.getAttribute("src");
    const url = raw && cdnHtml(raw);

    if (url) {
      frame.removeAttribute("src");
      fill(frame, url);
    }
  }

  function scan(root) {
    if (root.nodeType !== 1) return;

    if (root.tagName.toUpperCase() === "IFRAME") {
      check(root);
    }

    if (root.querySelectorAll) {
      root.querySelectorAll("iframe[src]").forEach(check);
    }
  }

  new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === "attributes") {
        check(mutation.target);
      } else {
        mutation.addedNodes.forEach(scan);
      }
    }
  }).observe(document, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["src"]
  });

  scan(document.documentElement);

  document.addEventListener("click", (event) => {
    const target = event.target;
    const anchor = target && target.closest
      ? target.closest("a[href]")
      : null;

    const url = anchor && cdnHtml(anchor.href);

    if (url) {
      event.preventDefault();
      window.__go(url);
    }
  }, true);

  const originalOpen = window.open;

  window.open = function(value, ...rest) {
    const url = value && cdnHtml(value);

    if (url) {
      window.__go(url);
      return null;
    }

    return originalOpen.call(window, value, ...rest);
  };
}

patch();

window.__fill(
  document.getElementById("test"),
  START
);
